(7734257, 1274745, 242379, '<td valign="top">Lovely image! The best one in this challenge</td>', 'Lovely image! The best one in this challenge', '2022-12-09 10:48:49.000000', NULL, 1),
(7734258, 1274783, 242379, '<td valign="top">Very nice picture In my top 3</td>', 'Very nice picture In my top 3', '2022-12-09 10:49:57.000000', NULL, 1),
(7734260, 1274756, 242379, '<td valign="top">Why do they say sheep are stupid? Tese look very curious and mischievous. Beautiful picture!</td>', 'Why do they say sheep are stupid? Tese look very curious and mischievous. Beautiful picture!', '2022-12-09 10:54:51.000000', NULL, 1),
(7734261, 1274763, 242379, '<td valign="top">I love this pic. In my top 3</td>', 'I love this pic. In my top 3', '2022-12-09 10:56:12.000000', NULL, 1),
(7734262, 1274825, 242379, '<td valign="top">Rural serenity. Very nice</td>', 'Rural serenity. Very nice', '2022-12-09 10:57:09.000000', NULL, 1),
(7734264, 1274811, 103142, '<td valign="top">I think you meant to put this in the flat lay still life? It''s beautiful and you should see if they can move it over.</td>', 'I think you meant to put this in the flat lay still life? It''s beautiful and you should see if they can move it over.', '2022-12-09 11:01:02.000000', NULL, 1),
(7734265, 1274799, 242379, '<td valign="top">NIt doesn´t look quite rural to me. But the title explains it. definitely it´s a perfect shot with great colors and framing.</td>', 'NIt doesn´t look quite rural to me. But the title explains it. definitely it´s a perfect shot with great colors and framing.', '2022-12-09 11:02:23.000000', NULL, 1),
(7734297, 1274688, 38162, '<td valign="top">love the scene but the overall edit seems over-cooked. GL.</td>', 'love the scene but the overall edit seems over-cooked. GL.', '2022-12-09 15:46:37.000000', NULL, 1),
(7734310, 1274829, 97225, '<td valign="top">I''m glad that someone did this.</td>', 'I''m glad that someone did this.', '2022-12-10 00:42:40.000000', NULL, 1),
(7734378, 1274831, 65234, '<td valign="top">How on earth did you get them mostly lined up and facing you?! Quite the variety of creatures, too. Well done.</td>', 'How on earth did you get them mostly lined up and facing you?! Quite the variety of creatures, too. Well done.', '2022-12-11 14:52:16.000000', NULL, 1),
(7734379, 1274745, 65234, '<td valign="top">Beautiful animals.</td>', 'Beautiful animals.', '2022-12-11 14:52:48.000000', NULL, 1),
(7734381, 1274825, 65234, '<td valign="top">Nicely composed. The cows add a nice bit of life to the scene.</td>', 'Nicely composed. The cows add a nice bit of life to the scene.', '2022-12-11 14:54:21.000000', NULL, 1),
(7734382, 1274826, 65234, '<td valign="top">One of the reasons I don''t like driving at night on rural roads! It''s just SO dark. And I''m just waiting for a suicidal deer to come running out of those trees.</td>', 'One of the reasons I don''t like driving at night on rural roads! It''s just SO dark. And I''m just waiting for a suicidal deer to come running out of those trees.', '2022-12-11 14:56:04.000000', NULL, 1),
(7734383, 1274821, 65234, '<td valign="top">I don''t usually see red churches; it certainly stands out. Pretty scene. There are some blurred areas on the rock wall on my left; not sure what they are.</td>', 'I don''t usually see red churches; it certainly stands out. Pretty scene. There are some blurred areas on the rock wall on my left; not sure what they are.', '2022-12-11 14:59:23.000000', NULL, 1),
(7734495, 1274745, 114285, '<td valign="top">WOW, is what I thought when I first viewed this! It''s amazing!<br/>Love the motion captured and the landscape.<br/> <br/>Top pick.</td>', 'WOW, is what I thought when I first viewed this! It''s amazing!Love the motion captured and the landscape. Top pick.', '2022-12-13 03:52:35.000000', NULL, 1),
(7734496, 1274831, 114285, '<td valign="top">What a beautiful collection of animals, just love the eye contact, so sweet.</td>', 'What a beautiful collection of animals, just love the eye contact, so sweet.', '2022-12-13 03:53:50.000000', NULL, 1),
(7734571, 1274816, 42733, '<td valign="top">My favorite in this challenge.</td>', 'My favorite in this challenge.', '2022-12-14 13:06:12.000000', NULL, 1),
(7734572, 1274783, 42733, '<td valign="top">In my top three for this challenge.</td>', 'In my top three for this challenge.', '2022-12-14 13:06:21.000000', NULL, 1),
(7734573, 1274811, 42733, '<td valign="top">In my top three for this challenge.</td>', 'In my top three for this challenge.', '2022-12-14 13:06:32.000000', NULL, 1),
(7734574, 1274745, 42733, '<td valign="top">Great action. Beautiful horses.</td>', 'Great action. Beautiful horses.', '2022-12-14 13:06:42.000000', NULL, 1),
(7734611, 1274763, 30049, '<td valign="top">This is fun. Tough shot if moving.  Kind of wish the front child was a little sharper but that''s a minor nit.  Good luck.</td>', 'This is fun. Tough shot if moving.  Kind of wish the front child was a little sharper but that''s a minor nit.  Good luck.', '2022-12-15 09:45:03.000000', NULL, 1),
(7734612, 1274745, 30049, '<td valign="top">Wow.  How excited must they be to be running free in this fresh pasture.  Look at all that grass for grazing!!!  Nice catch.</td>', 'Wow.  How excited must they be to be running free in this fresh pasture.  Look at all that grass for grazing!!!  Nice catch.', '2022-12-15 09:46:25.000000', NULL, 1),
(7734613, 1274832, 30049, '<td valign="top">Cool prop for a Christmas tree sale location.  Nice.</td>', 'Cool prop for a Christmas tree sale location.  Nice.', '2022-12-15 09:47:00.000000', NULL, 1),
(7734614, 1274744, 30049, '<td valign="top">Ruh-roh.  Imagine the stories that could be told by those trees if they could talk.  Sadly, the foreground tree isn''t far behind the barn. We''ve lost oaks that look like that one with the shedding branches, etc. Nice DOF on this.</td>', 'Ruh-roh.  Imagine the stories that could be told by those trees if they could talk.  Sadly, the foreground tree isn''t far behind the barn. We''ve lost oaks that look like that one with the shedding branches, etc. Nice DOF on this.', '2022-12-15 09:49:24.000000', NULL, 1),
(7734616, 1274826, 30049, '<td valign="top">Watch out for deer!  I take it the original was quite noisy?</td>', 'Watch out for deer!  I take it the original was quite noisy?', '2022-12-15 09:50:03.000000', NULL, 1),
(7734617, 1274824, 30049, '<td valign="top">Old family cemetery too.  Neat.</td>', 'Old family cemetery too.  Neat.', '2022-12-15 09:51:04.000000', NULL, 1),
(7734618, 1274738, 30049, '<td valign="top">It is very thin pickings now isn''t it?  Looks like more closer to the buildings.  Nice use of pano for this.  Too bad you couldn''t get lucky with a more interesting sky over the distant hills.</td>', 'It is very thin pickings now isn''t it?  Looks like more closer to the buildings.  Nice use of pano for this.  Too bad you couldn''t get lucky with a more interesting sky over the distant hills.', '2022-12-15 09:52:49.000000', NULL, 1),
(7734619, 1274831, 30049, '<td valign="top">You definitely have their attention!  :-)  WAY too much noise reduction applied IMO.  Details are totally blown away.</td>', 'You definitely have their attention!  :-)  WAY too much noise reduction applied IMO.  Details are totally blown away.', '2022-12-15 09:54:18.000000', NULL, 1),
(7734620, 1274825, 30049, '<td valign="top">Yep, yep.  Definitely rural. Nicely seen.  The reds are slightly over the top in the foreground / lower third of this image.  Guess you pushed the saturation to pop the barn?  Dup layer and erase thru, or masking, would have kept those areas more neutral brown.  Just one persons opinion.  Good luck.</td>', 'Yep, yep.  Definitely rural. Nicely seen.  The reds are slightly over the top in the foreground / lower third of this image.  Guess you pushed the saturation to pop the barn?  Dup layer and erase thru, or masking, would have kept those areas more neutral brown.  Just one persons opinion.  Good luck.', '2022-12-15 09:56:46.000000', NULL, 1),
(7734621, 1274822, 30049, '<td valign="top">Nice location.  Seems a bit flat (contrast washed out some).</td>', 'Nice location.  Seems a bit flat (contrast washed out some).', '2022-12-15 09:57:46.000000', NULL, 1),
(7734622, 1274816, 30049, '<td valign="top">Pop goes the colors!!!  :-)  The red object next to the person and their shirt - wow, VERY vivid.  Gives away the sat push.</td>', 'Pop goes the colors!!!  :-)  The red object next to the person and their shirt - wow, VERY vivid.  Gives away the sat push.', '2022-12-15 09:58:49.000000', NULL, 1),
(7734623, 1274799, 30049, '<td valign="top">Looks alien.  Not sure about Rural, but different for sure.</td>', 'Looks alien.  Not sure about Rural, but different for sure.', '2022-12-15 09:59:44.000000', NULL, 1),
(7734624, 1274811, 30049, '<td valign="top">Practice for Flat Lay?  ;-)</td>', 'Practice for Flat Lay?  ;-)', '2022-12-15 10:00:16.000000', NULL, 1),
(7734625, 1274699, 30049, '<td valign="top">I bet this looks really cool with fall colors on that tree.</td>', 'I bet this looks really cool with fall colors on that tree.', '2022-12-15 10:01:00.000000', NULL, 1),
(7734626, 1274729, 30049, '<td valign="top">:-)  Fun find.  From an editing standpoint I''d reduce the yellows and add a slight vig to anchor the subject.</td>', ':-)  Fun find.  From an editing standpoint I''d reduce the yellows and add a slight vig to anchor the subject.', '2022-12-15 10:02:06.000000', NULL, 1),
(7734627, 1274821, 30049, '<td valign="top">Wow!  I''ve never seen a church in red before.  Interesting.</td>', 'Wow!  I''ve never seen a church in red before.  Interesting.', '2022-12-15 10:02:46.000000', NULL, 1),
(7734628, 1274820, 30049, '<td valign="top">Definitely a rural / farm scene.  Very rich green grass.  Looks like this was taken from a moving vehicle maybe?  Some blur to it and not quite sharp.  Slight lean to the left also (the buildings aren''t quite level).  That solo tree sticking up would be a good candidate for "removing a distracting object" in the challenge rules.  :-)</td>', 'Definitely a rural / farm scene.  Very rich green grass.  Looks like this was taken from a moving vehicle maybe?  Some blur to it and not quite sharp.  Slight lean to the left also (the buildings aren''t quite level).  That solo tree sticking up would be a good candidate for "removing a distracting object" in the challenge rules.  :-)', '2022-12-15 10:06:19.000000', NULL, 1),
(7734629, 1274718, 30049, '<td valign="top">At one time somebody really liked that little tractor.  Wonder what stories are attached to it?  Many I''d wager.  Good luck.  Nice rural scene.</td>', 'At one time somebody really liked that little tractor.  Wonder what stories are attached to it?  Many I''d wager.  Good luck.  Nice rural scene.', '2022-12-15 10:07:35.000000', NULL, 1),
(7734630, 1274756, 30049, '<td valign="top">Some odd angles in this.  Fence going to the left, trees to the right, little overall left tilt.  Wide angle lens perhaps?</td>', 'Some odd angles in this.  Fence going to the left, trees to the right, little overall left tilt.  Wide angle lens perhaps?', '2022-12-15 10:09:55.000000', NULL, 1),
(7734631, 1274823, 30049, '<td valign="top">A little less could be more here.  Almost too much landscape and the sheep get diminished.  Not that you''d want the sheep, in a rural challenge theme, to be the primary subject, but a little more maybe?  Sorry.  Just thinking out loud on first impression of the image.  Good luck.</td>', 'A little less could be more here.  Almost too much landscape and the sheep get diminished.  Not that you''d want the sheep, in a rural challenge theme, to be the primary subject, but a little more maybe?  Sorry.  Just thinking out loud on first impression of the image.  Good luck.', '2022-12-15 10:11:46.000000', NULL, 1),
(7734644, 1274688, 29535, '<td valign="top">Great dramatic conditions and good composition apart from the little distraction on the right there, maybe a tighter crop would make a big difference. A little noisy after the edit, but my favourite image so far.<br/> <br/>But what a great sense of being there! I like the colours too.</td>', 'Great dramatic conditions and good composition apart from the little distraction on the right there, maybe a tighter crop would make a big difference. A little noisy after the edit, but my favourite image so far. But what a great sense of being there! I like the colours too.', '2022-12-15 12:33:51.000000', NULL, 1),
(7734645, 1274820, 29535, '<td valign="top">It''s a little soft for me unfortunately but I think you have a good choice of subject, the juxtaposition of the colours between the equipment and the environment could make for a great shot. If you get a chance to return, definitely revisit this idea!</td>', 'It''s a little soft for me unfortunately but I think you have a good choice of subject, the juxtaposition of the colours between the equipment and the environment could make for a great shot. If you get a chance to return, definitely revisit this idea!', '2022-12-15 12:35:01.000000', NULL, 1),
(7734646, 1274783, 29535, '<td valign="top">Simple and outside the box. I like the idea and the composition. If the wire was razor-sharp, pun absolutely intended, I would have even rated this my favourite image so far. But it''s just a tad soft...</td>', 'Simple and outside the box. I like the idea and the composition. If the wire was razor-sharp, pun absolutely intended, I would have even rated this my favourite image so far. But it''s just a tad soft...', '2022-12-15 12:35:55.000000', NULL, 1),
(7734647, 1274738, 29535, '<td valign="top">Perhaps it''s the Christmas season and binge-watching bad Hallmark movies but this is a lovely location, subject and composition. Great crop choice too!</td>', 'Perhaps it''s the Christmas season and binge-watching bad Hallmark movies but this is a lovely location, subject and composition. Great crop choice too!', '2022-12-15 12:36:06.000000', NULL, 1),
(7734648, 1274831, 29535, '<td valign="top">I''m giving marks just for getting the whole family to look at you for the photo, this would have been hard enough with humans!</td>', 'I''m giving marks just for getting the whole family to look at you for the photo, this would have been hard enough with humans!', '2022-12-15 12:36:39.000000', NULL, 1),
(7734649, 1274821, 29535, '<td valign="top">The fog/smudge on the left distracts from an otherwise good composition. I would love to see this shot revisited for perhaps the perfect angle. What great contrast between the church and the surroundings!</td>', 'The fog/smudge on the left distracts from an otherwise good composition. I would love to see this shot revisited for perhaps the perfect angle. What great contrast between the church and the surroundings!', '2022-12-15 12:39:38.000000', NULL, 1),
(7734650, 1274801, 29535, '<td valign="top">I like the idea and it''s a solid composition. I wonder if it can be exploited better from a different angle, and perhaps with a more muted colour saturation? Definitely worth a revisit.</td>', 'I like the idea and it''s a solid composition. I wonder if it can be exploited better from a different angle, and perhaps with a more muted colour saturation? Definitely worth a revisit.', '2022-12-15 12:41:11.000000', NULL, 1),
(7734652, 1274756, 29535, '<td valign="top">This is wonderful, great job. For me when people get portraits of animals that transmit character as well as a portrait of a human that''s a big win.</td>', 'This is wonderful, great job. For me when people get portraits of animals that transmit character as well as a portrait of a human that''s a big win.', '2022-12-15 12:41:56.000000', NULL, 1),
(7734653, 1274832, 29535, '<td valign="top">The filter is unnecessary (and possibly rule-breaking? Perhaps I''ve been away too long) which is a shame as this is an otherwise great subject! Love the idea that this old truck is still running. I''d love to see if you have some other shots of the same day.<br/> <br/>EDIT - I got justifiably corrected that I needed to brush up on my rules before commenting :) I apologise that I suggested the filter was rule-breaking, I''m coming back after 15 years and despite me trying to edit/delete the comment after realising my error it seems to have stuck!<br/> <br/>Thanks to glad2badad for pointing out my mistake and giving me the chance to correct myself here.<br/> <br/>In my defence I voted quite high on this image as if the filter wasn''t there, as I think the composition and subject deserves it. Good job! <br/><br/><i>Message edited by author 2022-12-16 07:07:54.</i></td>', 'The filter is unnecessary (and possibly rule-breaking? Perhaps I''ve been away too long) which is a shame as this is an otherwise great subject! Love the idea that this old truck is still running. I''d love to see if you have some other shots of the same day. EDIT - I got justifiably corrected that I needed to brush up on my rules before commenting :) I apologise that I suggested the filter was rule-breaking, I''m coming back after 15 years and despite me trying to edit/delete the comment after realising my error it seems to have stuck! Thanks to glad2badad for pointing out my mistake and giving me the chance to correct myself here. In my defence I voted quite high on this image as if the filter wasn''t there, as I think the composition and subject deserves it. Good job! ', '2022-12-15 12:44:34.000000', '2022-12-16 07:07:54.000000', 1),
(7734697, 1274821, 30214, '<td valign="top">https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1274821#</td>', 'https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1274821#', '2022-12-15 23:56:14.000000', NULL, 1),
(7734700, 1274745, 114285, '<td valign="top">Not surprised this won Roz. Also I  didn''t pick this as yours on the first round, but later when I looked at the trees I figured it was yours or Marion''s. <br/> <br/>Such a beautiful flowing image that brought joy on first view. You should be proud of this one, it stood out by far!<br/> <br/>I love the processing, so smooth and elegant. Well done!</td>', 'Not surprised this won Roz. Also I  didn''t pick this as yours on the first round, but later when I looked at the trees I figured it was yours or Marion''s.  Such a beautiful flowing image that brought joy on first view. You should be proud of this one, it stood out by far! I love the processing, so smooth and elegant. Well done!', '2022-12-16 00:04:09.000000', NULL, 0),
(7734701, 1274825, 114285, '<td valign="top">Lovely shot, and not a drone :)<br/> <br/>Super glad they''ve kept the farm, otherwise most kids would think that milk comes from a plastic bottle!</td>', 'Lovely shot, and not a drone :) Super glad they''ve kept the farm, otherwise most kids would think that milk comes from a plastic bottle!', '2022-12-16 00:08:07.000000', NULL, 0),
(7734702, 1274818, 68504, '<td valign="top">like. not enough is celebrated of smudges, their ponderings, insinuations, messy kisses.</td>', 'like. not enough is celebrated of smudges, their ponderings, insinuations, messy kisses.', '2022-12-16 00:14:02.000000', NULL, 0),
(7734703, 1274831, 114285, '<td valign="top">So adorable, where was this??</td>', 'So adorable, where was this??', '2022-12-16 00:14:20.000000', NULL, 0),
(7734704, 1274829, 68504, '<td valign="top">at last a conversation.</td>', 'at last a conversation.', '2022-12-16 00:14:40.000000', NULL, 0),
(7734705, 1274801, 123833, '<td valign="top">I was wondering about your choice of processing - smooth sky, everything else sharp and vivid. I like the composition, it leads me from the rocks through the ruins to the tower. <br/> <br/>I can see some chromatic aberration on the tower and blur in the bottom left corner. Were they intentional?</td>', 'I was wondering about your choice of processing - smooth sky, everything else sharp and vivid. I like the composition, it leads me from the rocks through the ruins to the tower.  I can see some chromatic aberration on the tower and blur in the bottom left corner. Were they intentional?', '2022-12-16 00:18:08.000000', NULL, 0),
(7734716, 1274811, 114285, '<td valign="top">I''d love to know what type of cake that is, looks super yummy! This flat lay was so lovely but I think people misinterpreted what you wanted to represent, which was probably a rustic theme, is that correct?</td>', 'I''d love to know what type of cake that is, looks super yummy! This flat lay was so lovely but I think people misinterpreted what you wanted to represent, which was probably a rustic theme, is that correct?', '2022-12-16 00:53:42.000000', NULL, 0),
(7734717, 1274763, 114285, '<td valign="top">It reminded me of the Yorkshire farm series, lovely shot.</td>', 'It reminded me of the Yorkshire farm series, lovely shot.', '2022-12-16 00:54:12.000000', NULL, 0),
(7734720, 1274756, 67145, '<td valign="top">such a great image Anita .. definitely a character shot .. :)<br/>had the neat stamp for sure .. sheep for one .. lol .. and one of your trademark tones .. you have a couple/few .. trademark tones that is .. <br/>i loved that the sheep are all looking at you .. and actually standing still .. did you hypnotize them haha .. ;)<br/> <br/>and its interesting how we all view things differently .. i didnt find anything odd about the angles at all .. especially as we have trees here that are leaning because of the prevailing winds .. often one will be leaning and one quite close wont be .. not sure why that is .. :)</td>', 'such a great image Anita .. definitely a character shot .. :)had the neat stamp for sure .. sheep for one .. lol .. and one of your trademark tones .. you have a couple/few .. trademark tones that is .. i loved that the sheep are all looking at you .. and actually standing still .. did you hypnotize them haha .. ;) and its interesting how we all view things differently .. i didnt find anything odd about the angles at all .. especially as we have trees here that are leaning because of the prevailing winds .. often one will be leaning and one quite close wont be .. not sure why that is .. :)', '2022-12-16 04:13:47.000000', NULL, 0),
(7734721, 1274756, 114285, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by roz:</b></div><hr/><i> such a great image Anita .. definitely a character shot .. :)<br/>had the neat stamp for sure .. sheep for one .. lol .. and one of your trademark tones .. you have a couple/few .. trademark tones that is .. <br/>i loved that the sheep are all looking at you .. and actually standing still .. did you hypnotize them haha .. ;)<br/> <br/>and its interesting how we all view things differently .. i didnt find anything odd about the angles at all .. especially as we have trees here that are leaning because of the prevailing winds .. often one will be leaning and one quite close wont be .. not sure why that is .. :) </i></td></tr></table> <br/> <br/>Yes the trees if they are not staked early then its too late A real pet hate of mine. Ive actually pulled out trees from my garden if they end up like that, I cant stand it, the perfectionist in me LOL.</td>', 'Originally posted by roz: such a great image Anita .. definitely a character shot .. :)had the neat stamp for sure .. sheep for one .. lol .. and one of your trademark tones .. you have a couple/few .. trademark tones that is .. i loved that the sheep are all looking at you .. and actually standing still .. did you hypnotize them haha .. ;) and its interesting how we all view things differently .. i didnt find anything odd about the angles at all .. especially as we have trees here that are leaning because of the prevailing winds .. often one will be leaning and one quite close wont be .. not sure why that is .. :)   Yes the trees if they are not staked early then its too late A real pet hate of mine. Ive actually pulled out trees from my garden if they end up like that, I cant stand it, the perfectionist in me LOL.', '2022-12-16 04:28:01.000000', NULL, 0),
(7734722, 1274756, 30049, '<td valign="top">Must have a LOT of wind!  :-)</td>', 'Must have a LOT of wind!  :-)', '2022-12-16 06:18:40.000000', NULL, 0),
